import { NextResponse } from 'next/server'
import { pigeons } from '@/lib/pigeons'

// POST /api/auth/verify-email
//
// Sends an email verification link to a user.
// The token is generated by your auth system and embedded in the
// verification URL. When the user clicks the link, your app validates
// the token and marks the email as verified.
//
// In production, generate a cryptographically secure token, store it
// with an expiry, and verify it when the user clicks through.
export async function POST(request: Request) {
  try {
    const body = await request.json()
    const { email, name, token } = body as { email: string; name: string; token: string }

    if (!email || !name || !token) {
      return NextResponse.json(
        { error: 'email, name, and token are required' },
        { status: 400 },
      )
    }

    // Build the verification URL with the token as a query param
    const verifyUrl = `https://yourapp.com/verify?token=${encodeURIComponent(token)}`

    // Send the verification email with inline HTML.
    // You could also use a template here instead.
    const sent = await pigeons.emails.send({
      to: email,
      subject: 'Verify your email address',
      html: `
        <h2>Hi ${name},</h2>
        <p>Thanks for signing up! Please verify your email address by clicking the link below:</p>
        <p><a href="${verifyUrl}">Verify my email</a></p>
        <p>This link expires in 24 hours.</p>
        <p>If you didn't create an account, you can safely ignore this email.</p>
      `,
      text: [
        `Hi ${name},`,
        '',
        'Thanks for signing up! Please verify your email address by visiting:',
        verifyUrl,
        '',
        'This link expires in 24 hours.',
        '',
        "If you didn't create an account, you can safely ignore this email.",
      ].join('\n'),
      tags: ['auth', 'verify-email'],
    })

    return NextResponse.json({
      message: 'Verification email sent',
      emailId: sent.id,
      status: sent.status,
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to send email'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}
